function VisualMark({ name, category, className = '' }: { name: string; category?: string; className?: string }) {
  const colors: Record<string, string> = { Vegetables: 'from-[#d6e3b7] to-[#8fa86b]', Fruit: 'from-[#f4d49c] to-[#d8894b]', Pulses: 'from-[#e8c9a8] to-[#ae7651]', 'Leafy greens': 'from-[#b6d7c0] to-[#5e9a73]', Roots: 'from-[#ded1bc] to-[#ae9570]', Pantry: 'from-[#f3d39d] to-[#ca8b47]' };
  return <div className={`relative overflow-hidden bg-gradient-to-br ${colors[category ?? 'Vegetables'] ?? 'from-[#d6e3b7] to-[#8fa86b]'} ${className}`}>
    <div className="absolute -right-8 -top-10 h-36 w-36 rounded-full border-[16px] border-white/20" />
    <div className="absolute -bottom-10 -left-8 h-32 w-32 rounded-full bg-white/20" />
    <div className="absolute inset-0 flex items-end justify-between p-4">
      <span className="font-display text-4xl leading-none text-[#18372c]/80">{name.charAt(0)}</span>
      <span className="rounded-full bg-[#fff9ed]/70 px-2 py-1 text-[10px] font-semibold uppercase tracking-[.15em] text-[#18372c]">{category ?? 'Produce'}</span>
    </div>
  </div>;
}

function Avatar({ farmer, size = 'md' }: { farmer: Pick<Farmer, 'name' | 'image'>; size?: 'sm' | 'md' | 'lg' }) {
  const sizes = { sm: 'h-8 w-8 text-[10px]', md: 'h-11 w-11 text-xs', lg: 'h-16 w-16 text-base' };
  return farmer.image ? <img src={farmer.image} alt={farmer.name} className={`${sizes[size]} rounded-full object-cover ring-2 ring-[#fff9ed]`} /> : <div className={`${sizes[size]} flex shrink-0 items-center justify-center rounded-full bg-[#d8e5cb] font-bold text-[#24523e] ring-2 ring-[#fff9ed]`}>{initials(farmer.name)}</div>;
}

function Button({ children, variant = 'primary', className = '', ...props }: React.ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'soft' | 'outline' | 'ghost' }) {
  const variants = {
    primary: 'bg-primary text-primary-foreground hover:translate-y-[-1px] hover:shadow-md',
    soft: 'bg-secondary text-secondary-foreground hover:bg-secondary/80',
    outline: 'border border-border bg-card text-foreground hover:border-primary/50 hover:bg-muted',
    ghost: 'text-muted-foreground hover:bg-muted hover:text-foreground',
  };
  return <button className={`focus-ring inline-flex min-h-10 items-center justify-center gap-2 rounded-full px-4 text-sm font-bold transition-all duration-200 disabled:pointer-events-none disabled:opacity-50 ${variants[variant]} ${className}`} {...props}>{children}</button>;
}

function Badge({ children, tone = 'green', className = '' }: { children: React.ReactNode; tone?: 'green' | 'orange' | 'cream'; className?: string }) {
  const tones = { green: 'bg-[#dcebd9] text-[#24523e]', orange: 'bg-[#f8dfc6] text-[#844a2c]', cream: 'bg-[#fff3d5] text-[#765323]' };
  return <span className={`inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-[11px] font-bold ${tones[tone]} ${className}`}>{children}</span>;
}

