        <div className="flex items-start justify-between gap-2"><div><p className="text-xs font-bold uppercase tracking-[.08em] text-muted-foreground">{product.category}</p><h3 className="mt-1 font-display text-[1.35rem] leading-tight">{product.name}</h3></div><Heart size={18} className="mt-1 shrink-0 text-muted-foreground transition-colors group-hover:text-accent" /></div>
