    <section className="grid gap-5 border-y border-border py-14 md:grid-cols-3 md:gap-0"><div className="border-border px-2 md:border-r md:px-8"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#dcebd9] text-primary"><ShieldCheck size={19} /></span><h3 className="mt-4 font-display text-2xl">Know your farmer</h3><p className="mt-2 max-w-xs text-sm leading-6 text-muted-foreground">Every seller is verified and every listing tells you where it came from.</p></div><div className="border-border px-2 md:border-r md:px-8"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#f8dfc6] text-accent"><Truck size={19} /></span><h3 className="mt-4 font-display text-2xl">Harvest to home</h3><p className="mt-2 max-w-xs text-sm leading-6 text-muted-foreground">Choose a delivery window that respects the freshness of your order.</p></div><div className="px-2 md:px-8"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#fff3d5] text-[#936d20]"><MessageCircle size={19} /></span><h3 className="mt-4 font-display text-2xl">A real conversation</h3><p className="mt-2 max-w-xs text-sm leading-6 text-muted-foreground">Ask a question before you buy. Farmers are one message away.</p></div></section>
